def add left right:
    total = left + right
    return total
def scaled left right factor:
    return (left + right) * factor
def largest left right:
    if left > right:
        return left
    return right
def pair left right:
    return [left, right]
def coordinates x y:
    return {x, y}
def noReturn left right:
    left + right
assert(add(2, 3), 5)
assert(scaled(2, 3, 4), 20)
assert(largest(7, 3), 7)
assert(largest(2, 9), 9)
assert(pair("left", "right"), ["left", "right"])
point = coordinates(2, 3)
assert(point.x, 2)
assert(point.y, 3)
assert(noReturn(2, 3), null)

class Pair:
    def init(a, b):
        this.a = a
        this.b = b
pair = Pair(b=2, a=1)
assert(pair, {"id": "pair", "a": 1, "b": 2})
